'use client';

import { Alert, Button, Container, Heading, Input, Label, StatusBadge, Table, Text } from '@medusajs/ui';
import { type FormEvent, useCallback, useEffect, useState } from 'react';

// WI-OI-085: the screen a module generated by `pnpm module:new` starts with, until it needs its own web package. It
// talks only to the module's manifest-declared gateway (`/api/<gateway>/v1/records`) and shows the server's answer.

interface RecordItem {
  readonly id: string;
  readonly title: string;
  readonly status: 'OPEN' | 'CLOSED';
  readonly version: number;
  readonly updatedAt: string;
}

export interface RecordsWorkspaceProps {
  /** The module's gateway segment, for example `inspections` for `/api/inspections`. */
  readonly gateway: string;
  readonly title: string;
}

async function call<T>(url: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  headers.set('Accept', 'application/json');
  const response = await fetch(url, { ...init, headers, cache: 'no-store' });
  if (response.status === 401 && typeof window !== 'undefined') window.location.assign('/login');
  const body: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const problem = body && typeof body === 'object' ? (body as Record<string, unknown>) : {};
    const nested =
      problem.message && typeof problem.message === 'object'
        ? (problem.message as Record<string, unknown>)
        : problem;
    const detail = [nested.message, problem.title].find((value) => typeof value === 'string');
    throw new Error((detail as string | undefined) ?? `Request failed (${response.status}).`);
  }
  return body as T;
}

export function RecordsWorkspace({ gateway, title }: RecordsWorkspaceProps) {
  const base = `/api/${encodeURIComponent(gateway)}/v1/records`;
  const [records, setRecords] = useState<readonly RecordItem[] | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    try {
      setRecords((await call<{ items: RecordItem[] }>(base)).items);
      setError(null);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'Records could not be loaded.');
    }
  }, [base]);

  useEffect(() => {
    void load();
  }, [load]);

  async function create(event: FormEvent) {
    event.preventDefault();
    setBusy(true);
    try {
      await call(base, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ requestKey: crypto.randomUUID(), title: newTitle }),
      });
      setNewTitle('');
      await load();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'The record could not be created.');
    } finally {
      setBusy(false);
    }
  }

  async function toggle(record: RecordItem) {
    setBusy(true);
    try {
      await call(`${base}/${record.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ version: record.version, status: record.status === 'OPEN' ? 'CLOSED' : 'OPEN' }),
      });
      await load();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'The record could not be changed.');
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex flex-col gap-4 p-6">
      <Container className="flex flex-col gap-4">
        <div>
          <Heading level="h1">{title}</Heading>
          <Text className="text-ui-fg-subtle" size="small">
            Records are stored by this module for your workspace only.
          </Text>
        </div>
        {error ? <Alert variant="error">{error}</Alert> : null}
        <form className="flex items-end gap-2" onSubmit={create}>
          <div className="flex flex-1 flex-col gap-1">
            <Label htmlFor="record-title">New record</Label>
            <Input
              id="record-title"
              value={newTitle}
              maxLength={200}
              onChange={(event) => setNewTitle(event.target.value)}
              placeholder="Title"
            />
          </div>
          <Button type="submit" isLoading={busy} disabled={busy || newTitle.trim().length === 0}>
            Add
          </Button>
        </form>
        {records === null ? (
          <Text className="text-ui-fg-subtle">Loading…</Text>
        ) : records.length === 0 ? (
          <Text className="text-ui-fg-subtle">No records yet.</Text>
        ) : (
          <div className="overflow-x-auto">
            <Table>
              <Table.Header>
                <Table.Row>
                  <Table.HeaderCell>Title</Table.HeaderCell>
                  <Table.HeaderCell>Status</Table.HeaderCell>
                  <Table.HeaderCell>Updated</Table.HeaderCell>
                  <Table.HeaderCell />
                </Table.Row>
              </Table.Header>
              <Table.Body>
                {records.map((record) => (
                  <Table.Row key={record.id}>
                    <Table.Cell>{record.title}</Table.Cell>
                    <Table.Cell>
                      <StatusBadge color={record.status === 'OPEN' ? 'green' : 'grey'}>
                        {record.status === 'OPEN' ? 'Open' : 'Closed'}
                      </StatusBadge>
                    </Table.Cell>
                    <Table.Cell className="tabular-nums text-ui-fg-subtle">
                      {new Date(record.updatedAt).toLocaleString()}
                    </Table.Cell>
                    <Table.Cell className="text-right">
                      <Button size="small" variant="secondary" disabled={busy} onClick={() => void toggle(record)}>
                        {record.status === 'OPEN' ? 'Close' : 'Reopen'}
                      </Button>
                    </Table.Cell>
                  </Table.Row>
                ))}
              </Table.Body>
            </Table>
          </div>
        )}
      </Container>
    </div>
  );
}
